//\nimport 'package:get/get.dart';\nimport '../utils/responsive.dart';\nimport '../widgets/responsive_builder.dart';\nimport '../widgets/loading_spinner.dart';\nimport '../services/message_service.dart';\n\n/// Example template for creating responsive views with loading states and messages\nclass ExampleResponsiveView extends StatelessWidget {\n  const ExampleResponsiveView({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    // Get your controller\n    final controller = Get.put(ExampleController());\n\n    return ResponsiveBuilder(\n      builder: (context, isDesktop, isTablet, isMobile) {\n        return Scaffold(\n          backgroundColor: const Color(0xFFE9F2F7),\n          // Loading overlay wraps everything\n          body: LoadingOverlay(\n            isLoading: controller.isLoading.value,\n            message: 'Processing...',\n            child: SafeArea(\n              child: Padding(\n                // Use responsive padding\n                padding: Responsive.responsivePaddingHorizontal,\n                child: SingleChildScrollView(\n                  child: ConstrainedBox(\n                    // Center content on desktop\n                    constraints: BoxConstraints(\n                      maxWidth: Responsive.maxContentWidth,\n                    ),\n                    child: Column(\n                      crossAxisAlignment: CrossAxisAlignment.stretch,\n                      children: [\n                        SizedBox(height: Responsive.blockSizeVertical * 2),\n                        // Title - responsive font size\n                        Text(\n                          'Example View',\n                          style: TextStyle(\n                            fontSize: Responsive.responsiveFontSize(28),\n                            fontWeight: FontWeight.w700,\n                          ),\n                        ),\n                        SizedBox(height: Responsive.blockSizeVertical * 1.5),\n                        // Subtitle\n                        Text(\n                          'This is a responsive example',\n                          style: TextStyle(\n                            fontSize: Responsive.responsiveFontSize(16),\n                            color: Colors.black54,\n                          ),\n                        ),\n                        SizedBox(height: Responsive.blockSizeVertical * 3),\n                        // Content Card\n                        _buildContentCard(context),\n                        SizedBox(height: Responsive.blockSizeVertical * 3),\n                        // Form Section\n                        _buildFormSection(context, controller),\n                        SizedBox(height: Responsive.blockSizeVertical * 3),\n                        // Action Buttons\n                        _buildButtonSection(context, controller),\n                        SizedBox(height: Responsive.blockSizeVertical * 2),\n                      ],\n                    ),\n                  ),\n                ),\n              ),\n            ),\n          ),\n        );\n      },\n    );\n  }\n\n  /// Builds a responsive content card\n  Widget _buildContentCard(BuildContext context) {\n    return Container(\n      width: double.infinity,\n      padding: EdgeInsets.all(Responsive.blockSizeHorizontal * 5),\n      decoration: BoxDecoration(\n        color: Colors.white,\n        borderRadius: BorderRadius.circular(Responsive.responsiveBorderRadius),\n        boxShadow: [\n          BoxShadow(\n            color: const Color.fromRGBO(0, 0, 0, 0.05),\n            blurRadius: 12,\n          ),\n        ],\n      ),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Text(\n            'Card Title',\n            style: TextStyle(\n              fontSize: Responsive.responsiveFontSize(20),\n              fontWeight: FontWeight.w700,\n            ),\n          ),\n          SizedBox(height: Responsive.blockSizeVertical * 1.5),\n          Text(\n            'This card adapts its size and text based on the device.',\n            style: TextStyle(\n              fontSize: Responsive.responsiveFontSize(14),\n              color: Colors.black54,\n              height: 1.6,\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  /// Builds a responsive form section\n  Widget _buildFormSection(BuildContext context, ExampleController controller) {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        Text(\n          'Form Section',\n          style: TextStyle(\n            fontSize: Responsive.responsiveFontSize(18),\n            fontWeight: FontWeight.w700,\n          ),\n        ),\n        SizedBox(height: Responsive.blockSizeVertical * 1.5),\n        // Text field with responsive sizing\n        TextFormField(\n          onChanged: (value) => controller.inputValue.value = value,\n          decoration: InputDecoration(\n            prefixIcon: const Icon(Icons.edit),\n            hintText: 'Enter text',\n            contentPadding: EdgeInsets.symmetric(\n              horizontal: Responsive.blockSizeHorizontal * 5,\n              vertical: Responsive.blockSizeVertical * 2,\n            ),\n          ),\n        ),\n      ],\n    );\n  }\n\n  /// Builds responsive button section\n  Widget _buildButtonSection(BuildContext context, ExampleController controller) {\n    return Column(\n      children: [\n        // Primary button with loading state\n        SizedBox(\n          width: double.infinity,\n          height: Responsive.buttonHeight,\n          child: Obx(\n            () => ElevatedButton(\n              onPressed: controller.isLoading.value ? null : controller.onPrimaryAction,\n              child: controller.isLoading.value\n                  ? const LoadingButtonIndicator()\n                  : Text(\n                      'Primary Action',\n                      style: TextStyle(\n                        fontSize: Responsive.responsiveFontSize(16),\n                      ),\n                    ),\n            ),\n          ),\n        ),\n        SizedBox(height: Responsive.blockSizeVertical * 1.5),\n        // Secondary button\n        SizedBox(\n          width: double.infinity,\n          height: Responsive.buttonHeight,\n          child: OutlinedButton(\n            onPressed: controller.onSecondaryAction,\n            child: Text(\n              'Secondary Action',\n              style: TextStyle(\n                fontSize: Responsive.responsiveFontSize(16),\n              ),\n            ),\n          ),\n        ),\n      ],\n    );\n  }\n}\n\n/// Example controller with loading states and message handling\nclass ExampleController extends GetxController {\n  final isLoading = false.obs;\n  final inputValue = ''.obs;\n\n  /// Handle primary action\n  Future<void> onPrimaryAction() async {\n    try {\n      isLoading.value = true;\n\n      // Simulate async operation\n      await Future.delayed(const Duration(seconds: 2));\n\n      // Show success message\n      await MessageService.showSuccess(\n        title: 'Success!',\n        message: 'Operation completed successfully',\n        confirmButtonText: 'OK',\n        onConfirm: () {\n          // Handle confirmation\n        },\n      );\n    } catch (e) {\n      // Show error message\n      await MessageService.showError(\n        title: 'Error',\n        message: 'Error: ${e.toString()}',\n        showRetry: true,\n        onRetry: onPrimaryAction,\n      );\n    } finally {\n      isLoading.value = false;\n    }\n  }\n\n  /// Handle secondary action\n  Future<void> onSecondaryAction() async {\n    // Show info message\n    await MessageService.showInfo(\n      title: 'Information',\n      message: 'This is informational content',\n      confirmButtonText: 'Got it',\n    );\n  }\n}\n\n// ============================================================================\n// QUICK COPY-PASTE SNIPPETS\n// ============================================================================\n\n/// SNIPPET 1: Basic responsive view wrapper\n// ResponsiveBuilder(\n//   builder: (context, isDesktop, isTablet, isMobile) {\n//     return Scaffold(\n//       body: YourContent(),\n//     );\n//   },\n// )\n\n/// SNIPPET 2: Responsive text\n// Text(\n//   'Your Text',\n//   style: TextStyle(\n//     fontSize: Responsive.responsiveFontSize(24),\n//   ),\n// )\n\n/// SNIPPET 3: Responsive padding\n// Padding(\n//   padding: Responsive.responsivePadding,\n//   child: YourWidget(),\n// )\n\n/// SNIPPET 4: Loading overlay\n// LoadingOverlay(\n//   isLoading: controller.isLoading.value,\n//   message: 'Loading...',\n//   child: YourContent(),\n// )\n\n/// SNIPPET 5: Responsive button\n// SizedBox(\n//   width: double.infinity,\n//   height: Responsive.buttonHeight,\n//   child: Obx(() => ElevatedButton(\n//     onPressed: controller.isLoading.value ? null : controller.onPressed,\n//     child: controller.isLoading.value\n//         ? const LoadingButtonIndicator()\n//         : const Text('Submit'),\n//   )),\n// )\n\n/// SNIPPET 6: Show success message\n// await MessageService.showSuccess(\n//   title: 'Success!',\n//   message: 'Operation completed',\n//   onConfirm: () => Get.back(),\n// );\n\n/// SNIPPET 7: Show error message\n// await MessageService.showError(\n//   title: 'Error',\n//   message: 'Something went wrong',\n//   showRetry: true,\n//   onRetry: () => retryAction(),\n// );\n\n/// SNIPPET 8: Device-specific layout\n// if (Responsive.isDesktop) {\n//   return DesktopLayout();\n// } else if (Responsive.isTabletPortrait) {\n//   return TabletLayout();\n// } else {\n//   return MobileLayout();\n// }\n"
